def bounded_process(argv, *, payload=b"", timeout=10, limit=OUTPUT_BYTES):
    # The old process-group cleanup and input/wall bounds are reused verbatim.
    return isolation.bounded_process(argv, payload=payload, timeout=timeout, limit=limit)


