def validation_base(validation, python_version):
    need(type(validation) is dict and "repeatability" in validation, "receipt_validation")
    base = dict(validation)
    repeatability = base.pop("repeatability")
    expected = dict(runs_checked=2, identical_canonical_bytes=True,
                    generation_python_version_reported=python_version,
                    validator_python_version=python_version, validator_python_implementation="CPython",
                    scope="these two supplied runs only; cross-version determinism is not established")
    need(exact(repeatability, expected)
         and hashlib.sha256(validator.canonical_json_bytes(base)).hexdigest() == VALIDATION_SHA256, "receipt_validation")
    return base


def validate_guard_evidence(value, receipt):
    """Bounded typed facts only; never accept raw properties or configuration."""
    h = host_contract
    def check(ok):
        need(ok, "receipt_guard_evidence")
    def integer(value, low=0, high=4294967295):
        return type(value) is int and low <= value <= high
    def enum(value, choices):
        return type(value) is str and value in choices
    check(type(value) is dict and set(value) == {"phase", "unit", "failed_predicates", "gate_check", "states", "settle"})
    check(enum(value["phase"], h.GUARD_PHASES)
          and (value["unit"] is None or enum(value["unit"], h.safety.UNITS))
          and enum(value["gate_check"], {"NOT_VERIFIED", "VERIFIED", "FAILED"}))
    check(receipt["gates_verified"] == (list(h.safety.GATE_UNITS) if value["gate_check"] == "VERIFIED" else []))
    failed = value["failed_predicates"]
    check(type(failed) is list and len(failed) <= 8
          and all(enum(item, h.GUARD_PREDICATES) for item in failed) and len(set(failed)) == len(failed))
    check(type(value["states"]) is list and len(value["states"]) == len(h.safety.UNITS))
    fields = {"observed", "active", "sub", "job_id", "main_pid_nonzero", "control_pid_nonzero",
              "cgroup_empty", "inactive_exit_us"}
    for unit, state in zip(h.safety.UNITS, value["states"]):
        check(type(state) is dict and set(state) == fields | {"unit"} and state["unit"] == unit
              and type(state["observed"]) is bool)
        if not state["observed"]:
            check(all(state[key] is None for key in fields - {"observed"}))
            continue
        check(enum(state["active"], h.safety.SAFE_STATES) and enum(state["sub"], h.safety.SAFE_SUB)
              and integer(state["job_id"]))
        check(all(type(state[key]) is bool for key in ("main_pid_nonzero", "control_pid_nonzero")))
        if unit == h.safety.TIMER:
            check(state["main_pid_nonzero"] is False and state["control_pid_nonzero"] is False)
        check(state["cgroup_empty"] is None or type(state["cgroup_empty"]) is bool)
        check(state["inactive_exit_us"] is None or integer(state["inactive_exit_us"], high=18446744073709551615))
        check(state["cgroup_empty"] is not None or state["inactive_exit_us"] is None)
    settle = value["settle"]
    check(type(settle) is dict and set(settle) == {"status", "polls", "elapsed_ms", "jobs"})
    check(enum(settle["status"], {"NOT_NEEDED", "WAITING", "SETTLED", "BLOCKED", "TIMEOUT"})
          and integer(settle["polls"], high=51) and integer(settle["elapsed_ms"], high=25000)
          and settle["elapsed_ms"] <= receipt["elapsed_ms"]
          and type(settle["jobs"]) is list and len(settle["jobs"]) <= len(h.safety.GATE_UNITS))
    for job in settle["jobs"]:
        check(type(job) is dict and set(job) == {"unit", "job_id", "type", "state", "execution_unchanged",
              "condition_skipped", "condition_before_us", "condition_after_us"})
        check(enum(job["unit"], h.safety.GATE_UNITS) and integer(job["job_id"], low=1)
              and job["type"] == "start" and enum(job["state"], {"waiting", "removed"})
              and type(job["execution_unchanged"]) is bool and type(job["condition_skipped"]) is bool
              and integer(job["condition_before_us"], high=18446744073709551615)
              and (job["condition_after_us"] is None or integer(job["condition_after_us"], high=18446744073709551615)))
        if job["condition_skipped"] or job["state"] == "removed":
            check(job["condition_skipped"] is True and job["state"] == "removed"
                  and job["condition_after_us"] is not None and job["condition_after_us"] > job["condition_before_us"])
    check(len({job["unit"] for job in settle["jobs"]}) == len(settle["jobs"]))
    if settle["status"] == "NOT_NEEDED":
        check(settle == dict(status="NOT_NEEDED", polls=0, elapsed_ms=0, jobs=[]))
    if settle["status"] == "SETTLED":
        check(settle["polls"] > 0 and bool(settle["jobs"]) and all(job["state"] == "removed"
              and job["condition_skipped"] is True and job["execution_unchanged"] is True for job in settle["jobs"]))
    if receipt["result"] == "WORLD_GENERATED":
        check(value["phase"] == "COMPLETE" and value["unit"] is None and failed == []
              and value["gate_check"] == "VERIFIED" and settle["status"] in {"NOT_NEEDED", "SETTLED"})
        check(all(state["observed"] is True and state["active"] == "inactive" and state["sub"] == "dead"
              and state["job_id"] == 0 and state["main_pid_nonzero"] is False
              and state["control_pid_nonzero"] is False and state["cgroup_empty"] is True
              and state["inactive_exit_us"] is not None for state in value["states"]))
    else:
        check(value["phase"] != "COMPLETE" and bool(failed) and receipt["reason"] in failed)
        if receipt["reason"] == "UNIT_BUSY":
            check(value["unit"] is not None)
            state = next(item for item in value["states"] if item["unit"] == value["unit"])
            check(state["observed"] is True)
            expected = [name for name, bad in (("ACTIVE_STATE", state["active"] != "inactive"),
                        ("SUB_STATE", state["sub"] != "dead"), ("MAIN_PID_NONZERO", state["main_pid_nonzero"] is not False),
                        ("CONTROL_PID_NONZERO", state["control_pid_nonzero"] is not False),
                        ("CGROUP_NOT_EMPTY", state["cgroup_empty"] is not True)) if bad]
            if state["job_id"] and (expected or state["unit"] not in h.safety.GATE_UNITS
                                    or value["phase"] not in {"PREFLIGHT", "SETTLING"}):
                expected.append("JOB_PENDING")
                if state["unit"] not in h.safety.GATE_UNITS:
                    expected.append("UNGATED_UNIT")
            check(bool(expected) and set(failed) == set(expected) | {"UNIT_BUSY"})
        if receipt["reason"] == "BOOT_SETTLE_TIMEOUT":
            check(settle["status"] == "TIMEOUT" and value["phase"] == "SETTLING"
                  and "JOB_PENDING" in failed and enum(value["unit"], h.safety.GATE_UNITS))
    # Exact keys, known enums and integer ranges already cap every field. This
    # final cap also protects the transported and exported nested evidence.
    check(len(validator.canonical_json_bytes(value)) <= 8192)


def validate_receipt(row, binding, *, revision=LEGACY_BUNDLE_REVISION):
    """No receipt-derived text is exported before exact schema/pin validation."""
    spec=bundle_revision(revision)
    need(type(row) is dict and set(row) == RECEIPT_KEYS, "receipt_schema")
    need(row["schema"] == host_contract.RECEIPT_SCHEMA and row["operation"] == "generate_worlds", "receipt_schema")
    need(all(type(row[k]) is type(v) and row[k] == v for k, v in binding.items()), "receipt_binding")
    need(row["snapshot_id"] == RESUME_SNAPSHOT_ID and row["snapshot_sha256"] == RESUME_SNAPSHOT_SHA256, "receipt_snapshot_binding")
    need(type(row["result"]) is str and row["result"] in {"WORLD_GENERATED", "BLOCKED"}, "receipt_result")
    need(type(row["reason"]) is str and row["reason"] in host_contract.REASONS, "receipt_reason")
    need(type(row["python_version"]) is str and re.fullmatch(r"[0-9]{1,2}\.[0-9]{1,2}\.[0-9]{1,3}", row["python_version"]), "receipt_python_version")
    need(row["generator_sha256"] == spec.source_pins["ibm_worlds_generator"] and row["input_sha256"] == validator.INPUT_SHA256, "receipt_source_binding")
    need(type(row["elapsed_ms"]) is int and 0 <= row["elapsed_ms"] <= host_contract.SECONDS * 1000, "receipt_elapsed")
    need(type(row["stage"]) is str and row["stage"] in STAGES and row["changes"] == [], "receipt_scope")
    need(type(row["gates_verified"]) is list and row["gates_verified"] in ([], list(host_contract.safety.GATE_UNITS)), "receipt_gates")
    scope = "/var/lib/bridge-school-maintenance/worlds-" + binding["run_id"] + "-" + binding["head"][:12]
    need(row["output_scope"] in (None, scope), "receipt_output_scope")
    need(row["scope_created"] is None or type(row["scope_created"]) is bool, "receipt_scope_created")
    restore_scope = "/var/lib/bridge-school-maintenance/" + RESUME_SNAPSHOT_ID + "/resume-restore-" + binding["run_id"] + "-" + binding["head"][:12]
    need(row["restore_scope"] in (None, restore_scope)
         and (row["restore_created"] is None or type(row["restore_created"]) is bool), "receipt_restore_scope")
    if row["restore_scope"] is None:
        need(row["restore_created"] is False, "receipt_restore_scope")
    if row["output_scope"] is None:
        need(row["scope_created"] is False, "receipt_scope_created")
    validate_guard_evidence(row["guard_evidence"], row)
    validation = row["validation"]
    if validation is not None:
        validation_base(validation, row["python_version"])
    if row["result"] == "WORLD_GENERATED":
        need(row["reason"] == "OK" and row["stage"] == "COMPLETE" and row["scope_created"] is True
             and row["output_scope"] == scope and row["gates_verified"] == list(host_contract.safety.GATE_UNITS)
             and row["restore_scope"] == restore_scope and row["restore_created"] is True
             and validation is not None, "receipt_incomplete")
        need(type(row["artifact"]) is dict, "receipt_artifact")
    else:
        need(row["reason"] != "OK" and row["stage"] != "COMPLETE" and row["artifact"] is None, "receipt_blocked")
    return row


def artifact_result(artifact):
    need(type(artifact) is dict and set(artifact) == {"name", "bytes", "sha256", "encoding", "data"}, "artifact_schema")
    need(artifact["name"] == "worlds.json" and artifact["encoding"] == "zlib+base64"
         and type(artifact["bytes"]) is int and artifact["bytes"] == 72174
         and artifact["sha256"] == validator.EXPECTED_RESULT_SHA256, "artifact_binding")
    data = artifact["data"]
    need(type(data) is str and 0 < len(data) <= 43692, "artifact_compressed_limit")
    try:
        compressed = base64.b64decode(data, validate=True)
        need(0 < len(compressed) <= 32768 and base64.b64encode(compressed).decode("ascii") == data, "artifact_compressed_limit")
        decoder = zlib.decompressobj()
        raw = decoder.decompress(compressed, ARTIFACT_BYTES + 1)
        need(len(raw) <= ARTIFACT_BYTES and decoder.eof and not decoder.unconsumed_tail and not decoder.unused_data, "artifact_decompressed_limit")
    except (ValueError, zlib.error):
        raise WorldsError("artifact_encoding") from None
    need(len(raw) == artifact["bytes"] and hashlib.sha256(raw).hexdigest() == artifact["sha256"], "artifact_digest")
    result = strict_json(raw)
    need(raw == validator.canonical_json_bytes(result), "artifact_canonical")
    try:
        independent = validator.validate_result(result, expected_result_sha256=validator.EXPECTED_RESULT_SHA256)
    except (ValueError, TypeError, KeyError):
        raise WorldsError("artifact_independent_validation") from None
    return raw, result, independent


def safe_receipt(receipt):
    row = dict(receipt)
    if row["artifact"] is not None:
        row["artifact"] = {key: value for key, value in row["artifact"].items() if key != "data"}
    return row


def export_manifest(receipt, binding, files, independent, *, revision=LEGACY_BUNDLE_REVISION):
    """The selected source identity is shared by export and lifecycle admission."""
    spec=bundle_revision(revision)
    return dict(schema="bridge.ibm.school-worlds.export.v1", source_commit=binding["head"],
                run_id=binding["run_id"], attempt=binding["attempt"], result=receipt["result"],
                snapshot_id=RESUME_SNAPSHOT_ID, snapshot_sha256=RESUME_SNAPSHOT_SHA256,
                input_sha256=validator.INPUT_SHA256, generator_sha256=spec.source_pins["ibm_worlds_generator"],
                reviewed_sources=dict(spec.source_pins), host_bundle_sha256=spec.host_source_sha,
                files={name: dict(bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest()) for name, raw in files.items()},
                validation=independent, purpose="COMPUTE_VERIFICATION_AND_TRAINING_INPUT_ONLY", service_changes=[])


def persist_receipt(receipt, binding, *, worlds=None, result=None, independent=None, revision=LEGACY_BUNDLE_REVISION):
    """Fresh runner-only directory and exclusive inert artifact files, never overwrite."""
    parent = Path(os.environ.get("RUNNER_TEMP", ""))
    need(parent.is_absolute() and parent.resolve(strict=True) == parent and parent.is_dir()
         and parent.stat().st_uid == os.geteuid(), "runner_output_scope")
    destination = parent / "ibm-school-worlds"
    try:
        os.mkdir(destination, 0o700)
    except FileExistsError:
        raise WorldsError("runner_output_collision") from None
    files = {"receipt.json": validator.canonical_json_bytes(safe_receipt(receipt))}
    if worlds is not None:
        need(result is not None and independent is not None, "runner_output_unverified")
        files.update({"worlds.json": worlds, "worlds.pbn": validator.render_pbn(result), "input.json": validator.INPUT_BYTES})
    manifest = export_manifest(receipt,binding,files,independent,revision=revision)
    files["manifest.json"] = validator.canonical_json_bytes(manifest)
    for name, raw in files.items():
        fd = os.open(destination / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try:
            with os.fdopen(fd, "wb") as output:
                output.write(raw)
                output.flush()
                os.fsync(output.fileno())
        except BaseException:
            # The owned exclusive partial directory remains truthful evidence;
            # neither an existing output nor old queue data is removed.
            raise
    return str(destination)


class PreparedWorlds:
    kind = "school_worlds"

    def __init__(self, binding, safe_source, host_source, keyfd, knownfd, *, revision=LEGACY_BUNDLE_REVISION):
        self.revision=revision
        self.bundle=bundle_revision(revision)
        self.binding, self.safe_source, self.host_source = binding, safe_source, host_source
        self.keyfd, self.knownfd = keyfd, knownfd
        self.ready, self.attempted, self.identity_bound = False, False, False
        self.output_path = None

    close = isolation.PreparedIsolation.close

    def bind_identity(self, identity):
        need(exact(identity, IDENTITY), "fresh_api_identity_required")
        self.identity_bound = True

    def call(self, phase, timeout):
        need(self.keyfd is not None and self.knownfd is not None, "transport_closed")
        parent = str(os.getpid())
        argv = ["/usr/bin/ssh", "-F", "/dev/null", "-T", "-i", "/proc/"+parent+"/fd/"+str(self.keyfd),
                "-o", "BatchMode=yes", "-o", "IdentitiesOnly=yes", "-o", "StrictHostKeyChecking=yes",
                "-o", "HostKeyAlgorithms=ssh-ed25519", "-o", "GlobalKnownHostsFile=/dev/null",
                "-o", "UserKnownHostsFile=/proc/"+parent+"/fd/"+str(self.knownfd),
                "-o", "UpdateHostKeys=no", "-o", "VerifyHostKeyDNS=no", "-o", "CheckHostIP=no",
                "-o", "AddKeysToAgent=no", "-o", "ForwardAgent=no", "-o", "ClearAllForwardings=yes",
                "-o", "ConnectionAttempts=1", "-o", "ConnectTimeout=3", "-o", "ServerAliveInterval=5", "-o", "ServerAliveCountMax=1",
                "ubuntu@"+read_only.ORACLE, "/usr/bin/python3 -I -B -c "+shlex.quote(remote_source(revision=self.revision))]
        request = None
        seconds = 28 if phase == "preflight" else timeout - 5
        need(phase in {"preflight", "generate_worlds"} and ((phase == "preflight" and timeout == 12)
             or (SSH_SECONDS <= seconds <= REMOTE_SECONDS)), "remote_budget")
        if phase == "generate_worlds":
            need(self.identity_bound, "fresh_api_identity_required")
            request = dict(schema="bridge.ibm.school-worlds.request.v1", operation="generate_worlds", **self.binding,
                           identity=IDENTITY, transport=TRANSPORT, snapshot_id=RESUME_SNAPSHOT_ID,
                           snapshot_sha256=RESUME_SNAPSHOT_SHA256)
        payload = json.dumps(dict(phase=phase, binding=self.binding, safe_source=self.safe_source,
                                  host_source=self.host_source, host_sha=self.bundle.host_source_sha, seconds=seconds, request=request)).encode()
        need(len(payload) <= INPUT_BYTES, "input_limit")
        return bounded_process(argv, payload=payload, timeout=timeout, limit=OUTPUT_BYTES)

    def preflight(self):
        rc, raw, err = self.call("preflight", 12)
        need(rc == 0 and len(raw) <= 2048 and not err, "oracle_preflight_failed")
        expected = dict(event="SCHOOL_WORLDS_ROUTE_READY", **self.binding, hostpin="MATCH", guest_network_requests=0)
        need(exact(strict_json(raw), expected), "oracle_preflight_schema")
        self.ready = True
        emit("SCHOOL_WORLDS_ROUTE_PREPARED", **self.binding, guest_network_requests=0)

    def run_once(self, *, max_seconds=MAINTENANCE_SECONDS):
        need(self.ready and not self.attempted and self.identity_bound, "not_ready_or_replay")
        need(type(max_seconds) in (int, float) and math.isfinite(max_seconds)
             and MIN_MAINTENANCE_SECONDS <= max_seconds <= MAINTENANCE_SECONDS, "maintenance_budget")
        self.attempted = True
        rc, raw, err = self.call("generate_worlds", max_seconds-5)
        need(type(rc) is int and type(raw) is bytes and type(err) is bytes and len(raw)+len(err) <= OUTPUT_BYTES, "transport_response")
        emit("SCHOOL_WORLDS_CAPTURED", **self.binding, remote_exit=rc, stdout_bytes=len(raw),
             stdout_sha256=hashlib.sha256(raw).hexdigest(), stderr_bytes=len(err),
             stderr_sha256=hashlib.sha256(err).hexdigest(), raw_output_exported=False)
        lines = raw.splitlines()
        need(0 < len(lines) <= 12 and all(0 < len(line) <= GUEST_RECEIPT_BYTES+512 for line in lines), "response_limit")
        rows = [strict_json(line) for line in lines]
        need(all(type(row) is dict and type(row.get("event")) is str for row in rows), "response_schema")
        events = [row["event"] for row in rows]
        allowed = {"RUN_BOUND_SCHOOL_WORLDS", "TCP_OPEN", "TCP_REFUSED", "TCP_TIMEOUT", "TCP_CONNECT_FAILURE",
                   "NETWORK_UNREACHABLE", "TCP_READINESS_EXHAUSTED", "SCHOOL_WORLDS_SSH_STARTED",
                   "SCHOOL_WORLDS_SSH_FINISHED", "SCHOOL_WORLDS_RECEIPT", "SCHOOL_WORLDS_ROUTE_BLOCKED"}
        need(set(events) <= allowed, "response_events")
        if exact(rows[0], dict(event="SCHOOL_WORLDS_ROUTE_BLOCKED", reason="bounded_transport_or_preflight_failed", raw_output_exported=False)):
            need(len(rows) == 1 and rc == 3 and not err, "response_blocked")
            return False
        need(exact(rows[0], dict(event="RUN_BOUND_SCHOOL_WORLDS", **self.binding)), "response_binding")
        chain = ["RUN_BOUND_SCHOOL_WORLDS", "TCP_OPEN", "SCHOOL_WORLDS_SSH_STARTED", "SCHOOL_WORLDS_SSH_FINISHED", "SCHOOL_WORLDS_RECEIPT"]
        if events != chain:
            return False
        tcp = rows[1]
        tcp_seconds = min(300, max_seconds-10-SSH_SECONDS)
        need(set(tcp) == {"event", "elapsed_seconds", "attempts"} and type(tcp["attempts"]) is int and 1 <= tcp["attempts"] <= 301
             and type(tcp["elapsed_seconds"]) in (int, float) and math.isfinite(tcp["elapsed_seconds"])
             and 0 <= tcp["elapsed_seconds"] <= round(tcp_seconds, 3), "tcp_receipt")
        need(exact(rows[2], dict(event="SCHOOL_WORLDS_SSH_STARTED", **self.binding)), "ssh_binding")
        finished = rows[3]
        need(set(finished) == set(self.binding) | {"event", "ssh_exit", "elapsed_seconds", "stdout_bytes", "stderr_bytes", "stdout_sha256", "stderr_sha256", "raw_output_exported"}
             and all(type(finished[k]) is type(v) and finished[k] == v for k, v in self.binding.items()), "ssh_receipt")
        need(type(finished["ssh_exit"]) is int and finished["ssh_exit"] in (0, 3) and finished["raw_output_exported"] is False
             and type(finished["elapsed_seconds"]) in (int, float) and math.isfinite(finished["elapsed_seconds"])
             and 0 <= finished["elapsed_seconds"] <= SSH_SECONDS, "ssh_receipt")
        for key in ("stdout_bytes", "stderr_bytes"):
            need(type(finished[key]) is int and 0 <= finished[key] <= GUEST_RECEIPT_BYTES, "ssh_receipt")
        need(finished["stdout_bytes"]+finished["stderr_bytes"] <= GUEST_RECEIPT_BYTES, "ssh_receipt")
        for key in ("stdout_sha256", "stderr_sha256"):
            need(type(finished[key]) is str and re.fullmatch("[0-9a-f]{64}", finished[key]), "ssh_receipt")
        holder = rows[4]
        need(set(holder) == set(self.binding) | {"event", "receipt"}
             and all(type(holder[k]) is type(v) and holder[k] == v for k, v in self.binding.items()), "receipt_binding")
        receipt = validate_receipt(holder["receipt"], self.binding, revision=self.revision)
        canonical = validator.canonical_json_bytes(receipt)
        need(len(canonical) <= GUEST_RECEIPT_BYTES and finished["stdout_bytes"] == len(canonical)
             and finished["stdout_sha256"] == hashlib.sha256(canonical).hexdigest()
             and finished["stderr_bytes"] == 0 and finished["stderr_sha256"] == hashlib.sha256(b"").hexdigest(), "receipt_capture_binding")
        success = rc == 0 and finished["ssh_exit"] == 0 and receipt["result"] == "WORLD_GENERATED"
        need((success and receipt["result"] == "WORLD_GENERATED") or
             (rc == 3 and finished["ssh_exit"] == 3 and receipt["result"] == "BLOCKED"), "receipt_exit_binding")
        worlds = result = independent = None
        if success:
            worlds, result, independent = artifact_result(receipt["artifact"])
            need(validator.canonical_json_bytes(validation_base(receipt["validation"], receipt["python_version"]))
                 == validator.canonical_json_bytes(independent), "receipt_validation")
        self.output_path = persist_receipt(receipt, self.binding, worlds=worlds, result=result, independent=independent, revision=self.revision)
        emit("SCHOOL_WORLDS_VERIFIED_RECEIPT", **self.binding, receipt=safe_receipt(receipt), artifact_path=self.output_path)
        return success


def prepare(*, revision=LEGACY_BUNDLE_REVISION):
    binding = context()
    source = Path(__file__).with_name("ibm_ssh_probe_safe.py").read_text()
    host = bundled_host_source(revision=revision)
    need(hashlib.sha256(source.encode()).hexdigest() == SAFE_SOURCE_SHA, "source_pin")
    raw = bytearray(os.environ.pop("ORACLE_SSH_PRIVATE_KEY", "").replace("\r", "").encode())
    need(32 < len(raw) < 32768, "existing_owner_key_missing")
    keyfd = knownfd = None
    try:
        keyfd = read_only.memory(raw, "existing-oracle-owner-key")
        for i in range(len(raw)):
            raw[i] = 0
        rc, scanned, _ = bounded_process(["/usr/bin/ssh-keyscan", "-T", "3", "-t", "ed25519", read_only.ORACLE], timeout=4, limit=8192)
        records = [row.split() for row in scanned.decode().splitlines() if row and not row.startswith('#')]
        need(rc == 0 and len(records) == 1 and records[0][:2] == [read_only.ORACLE, "ssh-ed25519"], "oracle_public_trust")
        fp = "SHA256:"+base64.b64encode(hashlib.sha256(base64.b64decode(records[0][2], validate=True)).digest()).decode().rstrip('=')
        need(fp == read_only.ORACLE_FP, "oracle_hostpin")
        knownfd = read_only.memory(scanned, "oracle-public-trust")
        probe = PreparedWorlds(binding, source, host, keyfd, knownfd, revision=revision)
        probe.preflight()
        return probe
    except BaseException:
        for fd in (knownfd, keyfd):
            if fd is not None:
                os.close(fd)
        raise
    finally:
        for i in range(len(raw)):
            raw[i] = 0
